let answerLockTs = null;

// Select-then-confirm within one group. `onLock` fires on the
// second click of the same option, matching the original.
const bindGroup = (root, onLock) => {
  const opts = Array.from(root.querySelectorAll('.kanji-opt'));
  let locked = false;
  opts.forEach(opt => {
    opt.addEventListener('click', () => {
      if (locked) return;
      if (opt.classList.contains('selected')) {
        opt.classList.remove('selected');
        opt.classList.add('locked');
        locked = true;
        root.classList.add('is-locked');
        onLock(opt);
      } else {
        opts.forEach(o => o.classList.remove('selected'));
        opt.classList.add('selected');
      }
    });
  });
};

const choices    = el.querySelector('#kanjiChoices');
const confidence = el.querySelector('#kanjiConfidence');

bindGroup(choices, (opt) => {
  const side = opt.getAttribute('data-side');
  answerLockTs = performance.now();
  screen.data.chosen_side  = side;
  screen.data.chosen_img   = side === 'left' ? screen.parameters.left_img : screen.parameters.right_img;
  screen.data.correct_side = screen.parameters.correct_side;
  screen.data.correct      = side === screen.parameters.correct_side ? 1 : 0;
  screen.data.rt_choice    = Math.round(answerLockTs - pageStart);
  confidence.hidden = false;
  // On short screens the scale sits below the fold. Bring it into view.
  confidence.scrollIntoView({ behavior: 'smooth', block: 'end' });
});

bindGroup(confidence, (opt) => {
